t="import unittest, tempfile, os
from pathlib import Path
from unittest.mock import patch
from daemon import key, persist, offset, open_db, mark, config, Blocked

class GatewayTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.store = open_db({"db":str(Path(self.temp.name)/"work.sqlite3")})
    def tearDown(self):
        self.store.close()
        self.temp.cleanup()
    def test_duplicate_update_persists_exactly_once(self):
        persist(self.store,42,7,"first")
        persist(self.store,42,7,"duplicate")
        self.assertEqual(offset(self.store),43)
        rows=self.store.execute("SELECT body FROM inbox").fetchall()
        self.assertEqual([r["body"] for r in rows],["first"])
    def test_offset_does_not_decrease(self):
        persist(self.store,10,1,"hi")
        persist(self.store,6,1,None)
        self.assertEqual(offset(self.store),11)
    def test_unknown_stays_unknown(self):
        persist(self.store,10,1,"task")
        mark(self.store,10,"SENDING_UNKNOWN")
        row=self.store.execute("SELECT state FROM inbox WHERE update_id=10").fetchone()
        self.assertEqual(row["state"],"SENDING_UNKNOWN")
    def test_stable_dedup_key(self):
        self.assertEqual(key(123),"telegram-curator-123")
    def test_no_configuration_fails_closed(self):
        with patch.dict(os.environ,{},clear=True):
            with self.assertRaises(Blocked): config()

if __name__=="__main__": unittest.main()
"
exec(compile(t,'test_daemon.py','exec'),{'__name__':'__main__'})
